import { readFile } from "node:fs/promises";
import { NextResponse } from "next/server";
import { uploadPath } from "@/server/storage";

const TYPES: Record<string, string> = { jpg: "image/jpeg", png: "image/png", webp: "image/webp" };

/**
 * Serves locally stored uploads. `next start` only sees files that were in public/ at build time,
 * so uploads can't live there. Names are generated by storeImage, and this strict pattern rules out
 * path traversal.
 */
export async function GET(_request: Request, context: { params: Promise<{ name: string }> }) {
  const { name } = await context.params;
  const match = /^[a-f0-9]{32}\.(jpg|png|webp)$/.exec(name);
  if (!match) return new NextResponse("Not found", { status: 404 });
  try {
    const file = await readFile(uploadPath(name));
    return new NextResponse(new Uint8Array(file), {
      headers: {
        "Content-Type": TYPES[match[1]],
        "Cache-Control": "public, max-age=31536000, immutable",
        "X-Content-Type-Options": "nosniff",
      },
    });
  } catch {
    return new NextResponse("Not found", { status: 404 });
  }
}
